/**
 * De-identified face wireframe from stored landmark geometry: rest reference
 * (thin, muted) with the expression overlaid (accent) and displacement
 * arrows at the measured points. No photograph is stored or shown.
 */
import { CONTOURS, SIDE, faceFrame, toFaceCoords, type Side, type Vec2 } from '../../core';

const unflat = (a: readonly number[]): Vec2[] => {
  const out: Vec2[] = [];
  for (let i = 0; i + 1 < a.length; i += 2) out.push({ x: a[i]!, y: a[i + 1]! });
  return out;
};

const KEY_POINTS = (s: Side) => [...SIDE[s].brow.slice(1, 3), SIDE[s].mouthCorner, SIDE[s].ala[0]!, SIDE[s].lidPairs[1]![0]];

interface Props {
  rest: readonly number[];
  expr?: readonly number[];
  view: 'mirror' | 'clinical';
  affectedSide: Side;
  label: string;
}

export function FaceWire({ rest, expr, view, affectedSide, label }: Props) {
  const restPx = unflat(rest);
  const frame = faceFrame(restPx);
  const R = toFaceCoords(frame, restPx);
  const E = expr ? toFaceCoords(frame, unflat(expr)) : null;
  // Mirror view: the patient's left appears on the viewer's left (like a mirror).
  const fx = (u: number) => (view === 'mirror' ? -u : u);
  const path = (F: readonly Vec2[], idx: readonly number[]) =>
    idx.map((i, k) => `${k ? 'L' : 'M'}${fx(F[i]!.x).toFixed(3)},${F[i]!.y.toFixed(3)}`).join(' ');
  const leftOnScreenLeft = view === 'mirror';
  const sideTag = (s: Side) => (s === affectedSide ? '마비 쪽' : '건강한 쪽');
  const arrows = E
    ? (['left', 'right'] as const).flatMap((s) => KEY_POINTS(s).map((i) => ({ a: R[i]!, b: E[i]!, aff: s === affectedSide })))
    : [];
  return (
    <svg class="wire" viewBox="-1.4 -1.2 2.8 3.0" role="img" aria-label={label}>
      <defs>
        <marker id="ah" viewBox="0 0 10 10" refX="7" refY="5" markerWidth="4" markerHeight="4" orient="auto-start-reverse">
          <path d="M0,0 L10,5 L0,10 z" fill="var(--series-2)" />
        </marker>
      </defs>
      {Object.values(CONTOURS).map((c) => (
        <path d={path(R, c)} fill="none" stroke="var(--axis)" stroke-width={E ? 0.012 : 0.018} stroke-linejoin="round" />
      ))}
      {E &&
        Object.values(CONTOURS).map((c) => (
          <path d={path(E, c)} fill="none" stroke="var(--accent)" stroke-width="0.018" stroke-linejoin="round" />
        ))}
      {arrows.map(({ a, b }) =>
        Math.hypot(b.x - a.x, b.y - a.y) > 0.012 ? (
          <line x1={fx(a.x)} y1={a.y} x2={fx(b.x)} y2={b.y} stroke="var(--series-2)" stroke-width="0.016" marker-end="url(#ah)" />
        ) : null,
      )}
      <text x="-1.32" y="-1.08" font-size="0.1" fill="var(--ink-2)">
        환자 {leftOnScreenLeft ? '왼쪽' : '오른쪽'} · {sideTag(leftOnScreenLeft ? 'left' : 'right')}
      </text>
      <text x="1.32" y="-1.08" font-size="0.1" fill="var(--ink-2)" text-anchor="end">
        환자 {leftOnScreenLeft ? '오른쪽' : '왼쪽'} · {sideTag(leftOnScreenLeft ? 'right' : 'left')}
      </text>
    </svg>
  );
}
