/**
 * 근육별 상세: one row per measured muscle action (affected side as % of the healthy side), with the muscles on the
 * face map and their rehab stretches. The map shows every muscle of the stretch programme; those the camera cannot
 * measure on their own are drawn paler and dashed with the result of the movement they share a nerve branch and
 * pull with. Tapping a row or a muscle shows only that on the map.
 */
import { useState } from 'preact/hooks';
import { MUSCLE_ORDER, isReferenceMuscle, type MuscleId, type MuscleResult } from '../../core';
import { stretchesFor } from '../anatomy/links';
import { Icon } from '../icons';
import { ANATOMY_NAME, AnatomyFace, type Anatomy, type AnatomyValues } from './FaceMap';
import { maxMm, ratioView } from '../labels';

const MUSCLE: Record<MuscleId, { name: string; action: string; muscles: readonly Anatomy[] }> = {
  frontalis: { name: '이마근', action: '눈썹 올리기', muscles: ['frontalis'] },
  orbOculiGentle: { name: '눈둘레근', action: '눈 살며시 감기', muscles: ['orbicularisOculi'] },
  orbOculiTight: { name: '눈둘레근', action: '눈 꽉 감기', muscles: ['orbicularisOculi'] },
  zygMajor: { name: '큰광대근', action: '입꼬리 위·바깥으로', muscles: ['zygMajor'] },
  upperLipLift: { name: '작은광대근·위입술올림근', action: '웃을 때 윗입술 올리기', muscles: ['zygMinor', 'lls'] },
  alaLift: { name: '위입술콧방울올림근', action: '콧방울 올리기', muscles: ['llsan'] },
  lipDepressors: { name: '입꼬리·아랫입술내림근', action: '아랫입술 내리기', muscles: ['depressors'] },
  orbOris: { name: '입둘레근', action: '입술 오므리기', muscles: ['orbicularisOris'] },
};

/** Muscles not measured on their own → the measured movement they share a nerve branch and pull with. */
const RELATED: Partial<Record<Anatomy, { from: MuscleId; why: string }>> = {
  corrugator: { from: 'frontalis', why: '같은 측두가지 신경' },
  lao: { from: 'zygMajor', why: '입꼬리를 함께 올림 · 같은 광대·볼가지 신경' },
  risorius: { from: 'zygMajor', why: '입꼬리를 옆으로 당김 · 같은 볼가지 신경' },
  buccinator: { from: 'orbOris', why: '입술·볼을 함께 오므림 · 같은 볼가지 신경' },
  platysma: { from: 'lipDepressors', why: '입꼬리·아랫입술을 함께 내림 · 목가지 신경' },
};

const pct = (x: number) => `${Math.round(100 * x)}%`;

function Stretches({ muscles }: { muscles: readonly Anatomy[] }) {
  const list = muscles.flatMap(stretchesFor);
  if (!list.length) return null;
  return (
    <div class="row wrap" style={{ gap: '6px', marginTop: '6px' }}>
      {list.map((s) => (
        <a class="btn sm" href={`#/exercise/${s.id}`}>
          {s.title} <Icon name="chev" />
        </a>
      ))}
    </div>
  );
}

export function MuscleCard({ m }: { m: MuscleResult }) {
  const [sel, setSel] = useState<MuscleId | null>(null);
  const [selA, setSelA] = useState<Anatomy | null>(null);
  const shown = MUSCLE_ORDER.filter((id) => m.items[id]);
  if (!shown.length) return null;
  const view = (id: MuscleId) => {
    const it = m.items[id];
    return ratioView(it?.ratio, maxMm(it?.mm));
  };
  // Too-small movements are left uncoloured: their ratio is not stable enough to call a muscle weak.
  const weakness = (id: MuscleId) => {
    const r = m.items[id]?.ratio;
    return r == null || view(id).kind === 'small' ? 0 : 1 - Math.max(0, Math.min(1, r));
  };
  // Map: the selected row or muscle only, else the weakest reading per muscle (reference items left out).
  const items = sel ? [sel] : selA ? [] : shown.filter((x) => !isReferenceMuscle(x));
  const values: AnatomyValues = {};
  for (const id of items) for (const a of MUSCLE[id].muscles) values[a] = Math.max(values[a] ?? 0, weakness(id));
  const inferred: AnatomyValues = {};
  for (const [a, r] of Object.entries(RELATED) as [Anatomy, { from: MuscleId }][])
    inferred[a] = (selA ? selA === a : items.includes(r.from)) && m.items[r.from] ? weakness(r.from) : 0;
  const related = selA ? RELATED[selA] : undefined;
  const from = related && m.items[related.from];
  return (
    <div class="card">
      <h3>근육별 상세</h3>
      <AnatomyFace
        affectedSide={m.affectedSide}
        values={values}
        inferred={inferred}
        tone="weak"
        selected={sel ? MUSCLE[sel].muscles : selA ? [selA] : []}
        onSelect={(a) => {
          const item = shown.find((id) => MUSCLE[id].muscles.includes(a) && id !== sel) ?? shown.find((id) => MUSCLE[id].muscles.includes(a));
          if (item) {
            setSel(item);
            setSelA(null);
          } else {
            setSel(null);
            setSelA(selA === a ? null : a);
          }
        }}
      />
      {selA && (
        <div class="list-item" style={{ display: 'block', cursor: 'default', marginTop: '8px' }}>
          <div class="small">
            <b>{ANATOMY_NAME[selA]}</b>
            <span class="muted"> · 직접 측정하지 않는 근육</span>
          </div>
          <div class="xsmall ink2" style={{ marginTop: '4px' }}>
            {related
              ? `${related.why}. ‘${MUSCLE[related.from].action}’ 결과${from?.ratio != null ? `(마비 쪽 ${view(related.from).text})` : ''}를 옅게 표시했습니다.`
              : '측정 항목과 연결되지 않은 근육입니다.'}
          </div>
          <Stretches muscles={[selA]} />
        </div>
      )}
      <div class="stack" style={{ gap: '6px', marginTop: '8px' }}>
        {MUSCLE_ORDER.map((id) => {
          const it = m.items[id];
          const d = MUSCLE[id];
          const ref = isReferenceMuscle(id);
          const on = sel === id;
          const v = view(id);
          return (
            <div class="list-item" style={{ display: 'block', cursor: 'default', border: on ? '2px solid var(--ink)' : undefined }}>
              <button
                style={{ display: 'block', width: '100%', textAlign: 'left', background: 'none', border: 0, padding: 0, cursor: 'pointer' }}
                onClick={() => {
                  setSel(on ? null : id);
                  setSelA(null);
                }}
              >
                <div class="row between">
                  <span class="small">
                    <b>{d.action}</b> <span class="muted">· {d.name}</span>
                    {ref && <span class="xsmall muted"> (참고)</span>}
                  </span>
                  <b
                    class="small"
                    style={{ whiteSpace: 'nowrap', marginLeft: '8px', color: v.kind === 'over' ? 'var(--warning-ink)' : v.kind === 'small' ? 'var(--muted)' : undefined }}
                  >
                    {!it ? '–' : v.text}
                  </b>
                </div>
                {it?.ratio != null && v.kind !== 'small' && (
                  <div aria-hidden="true" style={{ height: '6px', marginTop: '4px', background: 'var(--surface-2)', borderRadius: '3px', overflow: 'hidden' }}>
                    <div style={{ width: pct(Math.min(1, it.ratio)), height: '100%', background: '#3e63dd', opacity: ref ? 0.45 : 1 }} />
                  </div>
                )}
              </button>
              {on && (
                <div class="xsmall ink2" style={{ marginTop: '4px' }}>
                  {!it
                    ? '정밀 평가에서 측정됩니다.'
                    : it.mm
                      ? `마비 쪽 ${it.mm[m.affectedSide].toFixed(1)} mm · 건강한 쪽 ${it.mm[m.affectedSide === 'right' ? 'left' : 'right'].toFixed(1)} mm`
                      : `마비 쪽 ${pct(it.movement[m.affectedSide])} · 건강한 쪽 ${pct(it.movement[m.affectedSide === 'right' ? 'left' : 'right'])} 감김`}
                  {it?.ratio == null && it ? ' · 건강한 쪽 움직임이 작아 비율을 내지 않았습니다.' : ''}
                  {v.note && <div style={{ marginTop: '2px' }}>{v.note}</div>}
                  <Stretches muscles={[...d.muscles, ...(Object.keys(RELATED) as Anatomy[]).filter((a) => RELATED[a]!.from === id)]} />
                </div>
              )}
            </div>
          );
        })}
      </div>
      <p class="xsmall muted">
        마비 쪽이 건강한 쪽만큼 움직이면 100%입니다(100~125%는 오차 범위로 보고 100%로 표시). 색이 진할수록 약합니다. ‘100% 넘음’은 마비 쪽이 더
        크게 움직인 것(과한 움직임 또는 오차), ‘움직임 작음’은 양쪽 모두 3 mm 미만이라 비교하기 어려운 것입니다. 점선 근육은 카메라로 따로 잴 수 없어, 같은 신경 가지로 함께
        움직이는 동작의 결과를 옅게 표시한 것입니다(측정값 아님). 줄이나 근육을 누르면 위치와 스트레칭이 보입니다. “참고”는 측정 정확도가 낮아
        점수에 쓰지 않는 항목입니다. 알고리즘 FPA-MUSC {m.algorithm.version} · 임상 검증 전.
      </p>
    </div>
  );
}
